"""Entidades, filtros y reglas puras de catálogos, productos, movimientos y auditoría."""from __future__ import annotationsfrom dataclasses import dataclass, fieldfrom datetime import datefrom decimal import Decimalfrom typing import Generic, TypeVarT = TypeVar("T")ZERO = Decimal(0)QUANTITY_PLACES = 3MONEY_PLACES = 4ALERT_SIN_STOCK = "SIN_STOCK"ALERT_BAJO_MINIMO = "BAJO_MINIMO"ALERT_SOBRE_MAXIMO = "SOBRE_MAXIMO"ALERT_CUALQUIERA = "CUALQUIERA"ALERT_LABELS = {    ALERT_SIN_STOCK: "Sin stock",    ALERT_BAJO_MINIMO: "Bajo mínimo",    ALERT_SOBRE_MAXIMO: "Sobre máximo",}NATURE_SIGN = {"ENTRADA": 1, "AJUSTE_POS": 1, "SALIDA": -1, "AJUSTE_NEG": -1}@dataclass(frozen=True)class Page(Generic[T]):    """Resultado paginado."""    items: list[T]    total: int    page: int    page_size: int    @property    def pages(self) -> int:        if self.page_size <= 0:            return 1        return max(1, -(-self.total // self.page_size))def compute_alert(    cantidad: Decimal,    stock_minimo: Decimal | None,    stock_maximo: Decimal | None,    *,    usar_stock_maximo: bool = True,) -> str | None:    """Aplica RB-08 a un producto activo."""    if cantidad <= ZERO:        return ALERT_SIN_STOCK    if stock_minimo is not None and cantidad <= stock_minimo:        return ALERT_BAJO_MINIMO    if usar_stock_maximo and stock_maximo is not None and cantidad > stock_maximo:        return ALERT_SOBRE_MAXIMO    return Nonedef decimal_places(value: Decimal) -> int:    """Número de decimales significativos de un Decimal."""    exponent = value.normalize().as_tuple().exponent    return max(0, -int(exponent)) if isinstance(exponent, int) else 0def is_whole(value: Decimal) -> bool:    return value == value.to_integral_value()# ---------- Catálogos ----------@dataclass(frozen=True)class FieldSpec:    name: str    label: str    kind: str = "text"  # text | bool | ref    required: bool = False    max_len: int = 200    ref_kind: str | None = None@dataclass(frozen=True)class CatalogKind:    key: str    label: str    singular: str    fields: tuple[FieldSpec, ...]    unique_fields: tuple[str, ...]    product_fk: strCATALOG_KINDS: dict[str, CatalogKind] = {    "categoria": CatalogKind(        key="categoria",        label="Categorías",        singular="Categoría",        fields=(            FieldSpec("nombre", "Nombre", required=True, max_len=100),            FieldSpec("descripcion", "Descripción", max_len=300),        ),        unique_fields=("nombre",),        product_fk="categoria_id",    ),    "marca": CatalogKind(        key="marca",        label="Marcas",        singular="Marca",        fields=(FieldSpec("nombre", "Nombre", required=True, max_len=100),),        unique_fields=("nombre",),        product_fk="marca_id",    ),    "unidad_medida": CatalogKind(        key="unidad_medida",        label="Unidades",        singular="Unidad",        fields=(            FieldSpec("codigo", "Código", required=True, max_len=10),            FieldSpec("nombre", "Nombre", required=True, max_len=60),            FieldSpec("permite_decimales", "Permite decimales", kind="bool"),        ),        unique_fields=("codigo", "nombre"),        product_fk="unidad_id",    ),    "proveedor": CatalogKind(        key="proveedor",        label="Proveedores",        singular="Proveedor",        fields=(            FieldSpec("nombre", "Nombre", required=True, max_len=150),            FieldSpec("documento", "RUC / documento", max_len=30),            FieldSpec("contacto", "Contacto", max_len=100),            FieldSpec("telefono", "Teléfono", max_len=30),            FieldSpec("email", "Correo", max_len=100),            FieldSpec("direccion", "Dirección", max_len=300),        ),        unique_fields=("nombre",),        product_fk="proveedor_id",    ),    "ubicacion": CatalogKind(        key="ubicacion",        label="Ubicaciones",        singular="Ubicación",        fields=(            FieldSpec("codigo", "Código", required=True, max_len=30),            FieldSpec("nombre", "Nombre", required=True, max_len=100),            FieldSpec("padre_id", "Ubicación padre", kind="ref", ref_kind="ubicacion"),        ),        unique_fields=("codigo",),        product_fk="ubicacion_id",    ),}# ---------- Productos ----------@dataclassclass ProductData:    """Datos editables de un producto."""    codigo: str    nombre: str    categoria_id: int    unidad_id: int    codigo_barras: str | None = None    descripcion: str | None = None    marca_id: int | None = None    proveedor_id: int | None = None    ubicacion_id: int | None = None    precio_compra: Decimal | None = None    precio_venta: Decimal | None = None    stock_minimo: Decimal | None = None    stock_maximo: Decimal | None = None    observaciones: str | None = None    activo: bool = True@dataclass(frozen=True)class ProductRecord:    """Producto con stock y nombres de catálogos para listados y detalle."""    id: int    codigo: str    nombre: str    categoria_id: int    unidad_id: int    codigo_barras: str | None    descripcion: str | None    marca_id: int | None    proveedor_id: int | None    ubicacion_id: int | None    precio_compra: Decimal | None    precio_venta: Decimal | None    stock_minimo: Decimal | None    stock_maximo: Decimal | None    observaciones: str | None    activo: bool    creado_en: str    actualizado_en: str    row_version: int    cantidad: Decimal    categoria: str    unidad: str    unidad_permite_decimales: bool    marca: str | None    proveedor: str | None    ubicacion: str | None    def as_data(self) -> ProductData:        return ProductData(            codigo=self.codigo,            nombre=self.nombre,            categoria_id=self.categoria_id,            unidad_id=self.unidad_id,            codigo_barras=self.codigo_barras,            descripcion=self.descripcion,            marca_id=self.marca_id,            proveedor_id=self.proveedor_id,            ubicacion_id=self.ubicacion_id,            precio_compra=self.precio_compra,            precio_venta=self.precio_venta,            stock_minimo=self.stock_minimo,            stock_maximo=self.stock_maximo,            observaciones=self.observaciones,            activo=self.activo,        )    def alert(self, *, usar_stock_maximo: bool = True) -> str | None:        if not self.activo:            return None        return compute_alert(            self.cantidad,            self.stock_minimo,            self.stock_maximo,            usar_stock_maximo=usar_stock_maximo,        )@dataclassclass ProductFilter:    """Filtros combinables de RF-060/061."""    texto: str = ""    categoria_id: int | None = None    marca_id: int | None = None    proveedor_id: int | None = None    ubicacion_id: int | None = None    estado: str | None = "ACTIVO"  # ACTIVO | INACTIVO | None = todos    alerta: str | None = None  # ALERT_*; ALERT_CUALQUIERA = cualquier alerta    precio_desde: Decimal | None = None    precio_hasta: Decimal | None = None    registrado_desde: date | None = None    registrado_hasta: date | None = None    usar_stock_maximo: bool = True    def describe(self) -> list[str]:        """Resumen legible de los filtros activos para reportes."""        parts: list[str] = []        if self.texto:            parts.append(f"Texto: {self.texto}")        if self.estado:            parts.append(f"Estado: {self.estado}")        if self.alerta:            parts.append(f"Alerta: {ALERT_LABELS.get(self.alerta, 'Cualquiera')}")        if self.precio_desde is not None:            parts.append(f"Precio venta desde: {self.precio_desde}")        if self.precio_hasta is not None:            parts.append(f"Precio venta hasta: {self.precio_hasta}")        if self.registrado_desde:            parts.append(f"Registrado desde: {self.registrado_desde.isoformat()}")        if self.registrado_hasta:            parts.append(f"Registrado hasta: {self.registrado_hasta.isoformat()}")        return parts# ---------- Movimientos ----------@dataclass(frozen=True)class MovementType:    id: int    codigo: str    nombre: str    naturaleza: str    requiere_motivo: bool    es_sistema: bool    activo: bool    @property    def signo(self) -> int:        return NATURE_SIGN[self.naturaleza]@dataclass(frozen=True)class MovementLine:    producto_id: int    cantidad: Decimal    precio_unitario: Decimal | None = None@dataclass(frozen=True)class MovementRequest:    tipo_codigo: str    fecha: date    lines: tuple[MovementLine, ...]    motivo: str | None = None    documento_referencia: str | None = None    observacion: str | None = None    importacion_id: int | None = None    movimiento_origen_id: int | None = None@dataclass(frozen=True)class RegisteredMovement:    movimiento_id: int    lines: tuple[tuple[int, Decimal, Decimal], ...]  # producto_id, anterior, resultante@dataclass(frozen=True)class MovementRow:    movimiento_id: int    detalle_id: int    fecha_movimiento: str    creado_en: str    tipo_codigo: str    tipo_nombre: str    naturaleza: str    producto_id: int    producto_codigo: str    producto_nombre: str    signo: int    cantidad: Decimal    stock_anterior: Decimal    stock_resultante: Decimal    precio_unitario: Decimal | None    usuario: str    motivo: str | None    documento_referencia: str | None    movimiento_origen_id: int | None    importacion_id: int | None@dataclassclass MovementFilter:    producto_id: int | None = None    movimiento_id: int | None = None    tipo_codigo: str | None = None    usuario_id: int | None = None    fecha_desde: date | None = None    fecha_hasta: date | None = None# ---------- Auditoría ----------@dataclass(frozen=True)class AuditRow:    id: int    fecha_hora: str    usuario_id: int | None    username: str | None    accion: str    entidad: str    entidad_id: str | None    valor_anterior: str | None    valor_nuevo: str | None    detalle: str | None    estacion: str | None@dataclassclass AuditFilter:    fecha_desde: date | None = None    fecha_hasta: date | None = None    username: str = ""    entidad: str = ""    accion: str = ""# ---------- Reportes ----------@dataclassclass ReportData:    """Tabla lista para pantalla, CSV, Excel y PDF."""    key: str    title: str    headers: list[str]    column_types: list[str]  # text | qty | money | int | date    rows: list[list[object]]    filters: list[str] = field(default_factory=list)    totals: list[object] | None = None